    double dist = r.length();
    if (dist < 1e-10) {
        return 1e20; // Handle division by zero (infinite potential)
    }
    double s_over_r = sigma / dist;
    double s_over_r_6 = s_over_r * s_over_r * s_over_r;
    s_over_r_6 = s_over_r_6 * s_over_r_6; // (sigma/r)^6 squared = (sigma/r)^12
    double s_over_r_12 = s_over_r_6 * s_over_r_6;
    return 4.0 * epsilon * (s_over_r_12 - s_over_r_6);
}

